# Detect header pointers captured BEFORE a pull and dereferenced AFTER the pull
# (any function, any pull helper), plus loop context.
pull_re = re.compile(r'\b(pskb_may_pull|pskb_pull|__pskb_pull_tail|skb_linearize|pskb_expand_head|skb_cow|skb_cow_head|skb_unclone|skb_share_check)\s*\(')
cap_re  = re.compile(r'^\s*(?:const\s+)?[\w\s\*]*?(\w+)\s*=\s*(?:\(.*?\)\s*)?(skb_header_pointer\s*\(|\(.*?\*\)\s*(?:skb->data|skb_network_header|skb_transport_header|skb_mac_header|eth_hdr|ip_hdr|ipv6_hdr|dccp_hdr|tcp_hdr|udp_hdr|mpls_hdr))')
call_re = re.compile(r'^\s*(?:const\s+)?[\w\s\*]*?(\w+)\s*=\s*(?:\(.*?\)\s*)?(?:skb_header_pointer\s*\(|\(.*?\*\)\s*(?:skb->data|skb_network_header|skb_transport_header|skb_mac_header|eth_hdr|ip_hdr|ipv6_hdr|dccp_hdr|tcp_hdr|udp_hdr|mpls_hdr))')

results = []
for root, dirs, files in os.walk('net'):
    for f in files:
        if not f.endswith('.c'):
            continue
        path = os.path.join(root, f)
        try:
            text = open(path, errors='replace').read()
        except Exception:
            continue
        lines = text.split('\n')
        # split into functions
        func_start = None; func_name = '?'
        for i, ln in enumerate(lines):
            if ln.startswith('{'):
                func_start = i
                prev = lines[i-1] if i > 0 else ''
                m = re.search(r'(\w+)\s*\($', prev.strip()) or re.search(r'(\w+)\s*\(', prev)
                func_name = m.group(1) if m else '?'
            elif ln.startswith('}') and func_start is not None:
                body = lines[func_start:i+1]
                pulls = [j for j,l in enumerate(body) if pull_re.search(l)]
                if len(pulls) >= 1:
                    first = min(pulls); last = max(pulls)
                    for j in range(first):
                        m = call_re.search(body[j])
                        if not m: continue
                        var = m.group(1)
                        # find deref between pulls or after last pull
                        for k in range(first+1, len(body)):
                            if re.search(r'\b'+re.escape(var)+r'\s*->|'+re.escape(var)+r'\s*\[|\*\s*'+re.escape(var)+r'\b', body[k]):
